// Plus Two entrance chemistry bank: Chemical equilibrium (not ionic equilibrium). Original fibub questions.
// Data used: R = 0.0821 L atm K^-1 mol^-1 (Kp, Kc) and 8.314 J K^-1 mol^-1 (van't Hoff, dG = -RT ln K); 2.303 RT at 298 K = 5.71 kJ/mol.
// PCl5 molar mass 208.5 (vapour density 104.25); N2O4 molar mass 92 (vapour density 46).
import { pick, int, choose, fmt, shuffleOpts, numOpts } from '../_entrance.js';

let _n = 0;
const EX = { 1: ['keam', 'cusat', 'comedk', 'jee-main', 'neet'], 2: ['keam', 'cusat', 'comedk', 'jee-main', 'neet'], 3: ['jee-main', 'neet', 'comedk'], 4: ['jee-main', 'jee-adv', 'neet'], 5: ['jee-adv'] };
const A4 = ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'];
const S4 = ['Both Statement I and Statement II are correct', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct', 'Both Statement I and Statement II are incorrect'];
const mk = (id, level, sub, q, right, wrongs, sol, trap) => {
  const pos = (_n++) % 4; const options = [...wrongs]; options.splice(pos, 0, right);
  return { id, type: 'mcq', level, format: 'single', exams: EX[level], sub, q, options, answer: pos, sol, ...(trap ? { trap } : {}) };
};
const nat = (id, level, sub, q, answer, tol, unit, sol, trap) => ({ id, type: 'nat', level, format: tol === 0 ? 'integer' : 'numeric', exams: EX[level], sub, q, answer, tol, ...(unit ? { unit } : {}), sol, ...(trap ? { trap } : {}) });
const msq = (id, level, sub, q, options, answer, sol, trap) => ({ id, type: 'msq', level, format: 'multi', exams: level >= 4 ? ['jee-adv'] : ['jee-adv', 'jee-main'], sub, q, options, answer, sol, ...(trap ? { trap } : {}) });
const asr = (id, level, sub, A, R, answer, sol, trap) => ({ id, type: 'mcq', level, format: 'assertion', exams: EX[level], sub, q: `<p><b>Assertion (A):</b> ${A}</p><p><b>Reason (R):</b> ${R}</p>`, options: A4, answer, sol, ...(trap ? { trap } : {}) });
const stm = (id, level, sub, s1, s2, answer, sol, trap) => ({ id, type: 'mcq', level, format: 'statements', exams: EX[level], sub, q: `<p><b>Statement I:</b> ${s1}</p><p><b>Statement II:</b> ${s2}</p>`, options: S4, answer, sol, ...(trap ? { trap } : {}) });
const mat = (id, level, sub, group, q, right, wrongs, sol, trap) => ({ ...mk(id, level, sub, q, right, wrongs, sol, trap), format: 'match', group });
const P = (id, level, sub, group, q, right, wrongs, sol, trap) => ({ ...mk(id, level, sub, q, right, wrongs, sol, trap), format: 'passage', group });
const PN = (id, level, sub, group, q, answer, tol, unit, sol, trap) => ({ ...nat(id, level, sub, q, answer, tol, unit, sol, trap), format: 'passage', group });

const RT = (T) => 0.0821 * T;
// gas reactions with change in moles of gas
const RX = [
  ['N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g)', -2], ['2SO<sub>2</sub>(g) + O<sub>2</sub>(g) &#8652; 2SO<sub>3</sub>(g)', -1], ['PCl<sub>5</sub>(g) &#8652; PCl<sub>3</sub>(g) + Cl<sub>2</sub>(g)', 1],
  ['N<sub>2</sub>O<sub>4</sub>(g) &#8652; 2NO<sub>2</sub>(g)', 1], ['H<sub>2</sub>(g) + I<sub>2</sub>(g) &#8652; 2HI(g)', 0], ['CO(g) + 2H<sub>2</sub>(g) &#8652; CH<sub>3</sub>OH(g)', -2], ['2NH<sub>3</sub>(g) &#8652; N<sub>2</sub>(g) + 3H<sub>2</sub>(g)', 2],
];
const UNIT = { '-2': 'L<sup>2</sup> mol<sup>-2</sup>', '-1': 'L mol<sup>-1</sup>', '0': 'no unit', '1': 'mol L<sup>-1</sup>', '2': 'mol<sup>2</sup> L<sup>-2</sup>' };
const UNITP = { '-2': 'atm<sup>-2</sup>', '-1': 'atm<sup>-1</sup>', '0': 'no unit', '1': 'atm', '2': 'atm<sup>2</sup>' };

export default {
  topic: 'chemical-equilibrium',
  groups: {
    m1: { title: 'N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g), &Delta;H &lt; 0. Match the change with its effect', list1: ['A. Increase the total pressure by compression', 'B. Raise the temperature', 'C. Add a catalyst', 'D. Add argon at constant volume'], list2: ['p. Equilibrium shifts towards N<sub>2</sub> and H<sub>2</sub>', 'q. Equilibrium shifts towards NH<sub>3</sub>', 'r. Same composition, reached sooner', 's. No change in any concentration'] },
    m2: { title: 'Match the reaction with the unit of K<sub>c</sub>', list1: ['A. N<sub>2</sub> + 3H<sub>2</sub> &#8652; 2NH<sub>3</sub>', 'B. N<sub>2</sub>O<sub>4</sub> &#8652; 2NO<sub>2</sub>', 'C. H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI', 'D. 2SO<sub>2</sub> + O<sub>2</sub> &#8652; 2SO<sub>3</sub>'], list2: ['p. No unit', 'q. mol L<sup>-1</sup>', 'r. L mol<sup>-1</sup>', 's. L<sup>2</sup> mol<sup>-2</sup>'] },
    m3: { title: 'Match the condition with the direction of the net reaction', list1: ['A. Q &lt; K', 'B. Q &gt; K', 'C. Q = K', 'D. Products absent at the start'], list2: ['p. Net backward reaction', 'q. System at equilibrium', 'r. Net forward reaction, &Delta;G &lt; 0', 's. Only the forward reaction occurs at first'] },
    m4: { title: 'Match the equilibrium with the expression for K<sub>p</sub>', list1: ['A. CaCO<sub>3</sub>(s) &#8652; CaO(s) + CO<sub>2</sub>(g)', 'B. NH<sub>4</sub>HS(s) &#8652; NH<sub>3</sub>(g) + H<sub>2</sub>S(g)', 'C. 2NH<sub>3</sub>(g) &#8652; N<sub>2</sub>(g) + 3H<sub>2</sub>(g)', 'D. C(s) + CO<sub>2</sub>(g) &#8652; 2CO(g)'], list2: ['p. p(NH<sub>3</sub>) &times; p(H<sub>2</sub>S)', 'q. p(CO)<sup>2</sup> / p(CO<sub>2</sub>)', 'r. p(CO<sub>2</sub>)', 's. p(N<sub>2</sub>) p(H<sub>2</sub>)<sup>3</sup> / p(NH<sub>3</sub>)<sup>2</sup>'] },
    p1: { title: 'Dinitrogen tetroxide in a closed vessel', passage: '<p>Pure N<sub>2</sub>O<sub>4</sub>(g), colourless, is placed in a rigid vessel at 400 K at an initial pressure of <b>1.00 atm</b>. It partly dissociates: N<sub>2</sub>O<sub>4</sub>(g) &#8652; 2NO<sub>2</sub>(g) (brown), &Delta;H = +57 kJ mol<sup>-1</sup>. At equilibrium the total pressure is <b>1.20 atm</b>.</p>' },
    p2: { title: 'The Haber process', passage: '<p>Ammonia is made by N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g), &Delta;H = -92 kJ mol<sup>-1</sup>. In industry the gases are passed over iron at about 700 K and 200 atm; the ammonia is cooled to a liquid and removed, and unreacted gases are recycled.</p>' },
    p3: { title: 'Compressing an equilibrium mixture', passage: '<p>In a closed flask at constant temperature, PCl<sub>5</sub>(g) &#8652; PCl<sub>3</sub>(g) + Cl<sub>2</sub>(g) is at equilibrium with [PCl<sub>5</sub>] = 0.40, [PCl<sub>3</sub>] = 0.20 and [Cl<sub>2</sub>] = 0.20 mol L<sup>-1</sup>. The volume is then suddenly halved and the mixture is allowed to reach a new equilibrium at the same temperature.</p>' },
  },
  items: [
    // ---------- Level 1 ----------
    mk('ce-001', 1, 'dynamic equilibrium', 'At chemical equilibrium in a closed vessel,', 'the rates of the forward and backward reactions are equal', ['the forward and backward reactions have stopped', 'the concentrations of reactants and products are equal', 'the reaction is complete'], '<p>Equilibrium is <b>dynamic</b>: both reactions go on, at equal rates, so concentrations stay constant. They are constant, not necessarily equal.</p>'),
    mk('ce-002', 1, 'law of mass action', 'For N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g), the expression for K<sub>c</sub> is', '[NH<sub>3</sub>]<sup>2</sup> / ([N<sub>2</sub>][H<sub>2</sub>]<sup>3</sup>)', ['[NH<sub>3</sub>] / ([N<sub>2</sub>][H<sub>2</sub>])', '[N<sub>2</sub>][H<sub>2</sub>]<sup>3</sup> / [NH<sub>3</sub>]<sup>2</sup>', '2[NH<sub>3</sub>] / ([N<sub>2</sub>] 3[H<sub>2</sub>])'], '<p>Products on top, reactants below, each raised to the power of its coefficient. Option B is K<sub>c</sub> for the reverse reaction.</p>'),
    mk('ce-003', 1, 'heterogeneous equilibrium', 'For CaCO<sub>3</sub>(s) &#8652; CaO(s) + CO<sub>2</sub>(g), K<sub>c</sub> is', '[CO<sub>2</sub>]', ['[CaO][CO<sub>2</sub>] / [CaCO<sub>3</sub>]', '[CaO] / [CaCO<sub>3</sub>]', '1 / [CO<sub>2</sub>]'], '<p>The concentration of a pure solid or liquid is constant and is taken as 1 in K, so only the gas appears: K<sub>c</sub> = [CO<sub>2</sub>] and K<sub>p</sub> = p(CO<sub>2</sub>).</p>'),
    mk('ce-004', 1, 'catalyst', 'A catalyst added to a reaction at equilibrium', 'speeds up both forward and backward reactions equally and does not change K', ['increases K', 'shifts the equilibrium towards products', 'decreases the activation energy of the forward reaction only'], '<p>A catalyst lowers the activation energy of both directions by the same amount, so equilibrium is reached sooner but its position and K are unchanged.</p>'),
    mk('ce-005', 1, 'K and temperature', 'The value of the equilibrium constant of a reaction depends on', 'temperature only', ['pressure only', 'initial concentrations', 'the presence of a catalyst'], '<p>For a given reaction K changes only with temperature. Concentration, pressure, volume or a catalyst may change the composition or the speed but not K.</p>'),
    mk('ce-006', 1, 'reaction quotient', 'If the reaction quotient Q is greater than K, the reaction proceeds', 'in the backward direction', ['in the forward direction', 'with no change', 'only if a catalyst is added'], '<p>Q &gt; K means there are too many products compared with equilibrium, so products are used up and the net reaction goes backward until Q = K.</p>'),
    mk('ce-007', 1, 'K<sub>p</sub> and K<sub>c</sub>', 'For which reaction is K<sub>p</sub> equal to K<sub>c</sub>?', 'H<sub>2</sub>(g) + I<sub>2</sub>(g) &#8652; 2HI(g)', ['N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g)', 'PCl<sub>5</sub>(g) &#8652; PCl<sub>3</sub>(g) + Cl<sub>2</sub>(g)', '2SO<sub>2</sub>(g) + O<sub>2</sub>(g) &#8652; 2SO<sub>3</sub>(g)'], '<p>K<sub>p</sub> = K<sub>c</sub>(RT)<sup>&Delta;n<sub>g</sub></sup>. They are equal only if &Delta;n<sub>g</sub> = 0. Only H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI has 2 mol of gas on each side.</p>'),
    mk('ce-008', 1, 'Le Chatelier principle', 'For N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g), increasing the pressure by reducing the volume', 'shifts the equilibrium to the right', ['shifts the equilibrium to the left', 'does not shift the equilibrium', 'changes the value of K'], '<p>The system opposes a rise in pressure by reducing the number of gas moles: 4 mol on the left, 2 mol on the right. So the equilibrium moves right (more NH<sub>3</sub>). K is unchanged.</p>'),
    mk('ce-009', 1, 'Le Chatelier principle', 'On heating, the equilibrium of an endothermic reaction', 'shifts towards the products', ['shifts towards the reactants', 'does not change', 'is destroyed'], '<p>Heat is like a reactant for an endothermic reaction. Adding heat favours the forward direction, which absorbs it, and K increases.</p>'),
    mk('ce-010', 1, 'units of K', 'The unit of K<sub>c</sub> for N<sub>2</sub>O<sub>4</sub>(g) &#8652; 2NO<sub>2</sub>(g) is', 'mol L<sup>-1</sup>', ['mol<sup>-1</sup> L', 'it has no unit', 'mol<sup>2</sup> L<sup>-2</sup>'], '<p>K<sub>c</sub> = [NO<sub>2</sub>]<sup>2</sup>/[N<sub>2</sub>O<sub>4</sub>] has units (mol L<sup>-1</sup>)<sup>2-1</sup> = mol L<sup>-1</sup>. The unit is (mol L<sup>-1</sup>)<sup>&Delta;n</sup>.</p>'),
    mk('ce-011', 1, 'meaning of K', 'A very large value of K (for example 10<sup>10</sup>) means that at equilibrium', 'products are strongly favoured', ['reactants are strongly favoured', 'the reaction is very fast', 'the reaction has stopped'], '<p>K is products over reactants, so a big K means mostly products. It says nothing about speed (that is rate and activation energy).</p>', 'K tells where the equilibrium lies, not how fast it is reached.'),
    mk('ce-012', 1, 'dynamic equilibrium', 'Which statement about the equilibrium H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI in a closed vessel is <b>not</b> correct?', '[H<sub>2</sub>] must equal [HI]', ['The colour of the mixture stays constant', 'The same equilibrium can be reached starting from pure HI', 'The forward and backward rates are equal'], '<p>Equilibrium needs constant concentrations, not equal ones. Starting from H<sub>2</sub> and I<sub>2</sub> or from HI alone gives the same equilibrium mixture at the same temperature.</p>'),

    // ---------- Level 2 ----------
    nat('ce-013', 2, 'calculating K<sub>c</sub>', 'At equilibrium for H<sub>2</sub>(g) + I<sub>2</sub>(g) &#8652; 2HI(g): [H<sub>2</sub>] = 0.10, [I<sub>2</sub>] = 0.10 and [HI] = 0.80 mol L<sup>-1</sup>. Find K<sub>c</sub>.', 64, 0, '', '<p>K<sub>c</sub> = [HI]<sup>2</sup>/([H<sub>2</sub>][I<sub>2</sub>]) = 0.64 / (0.10 &times; 0.10) = <b>64</b>. No unit since &Delta;n = 0.</p>', 'Forgetting to square [HI] gives 80.'),
    nat('ce-014', 2, 'reversing an equation', 'For H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI, K<sub>c</sub> = 64 at a certain temperature. Find K<sub>c</sub> for 2HI &#8652; H<sub>2</sub> + I<sub>2</sub> at the same temperature.', 0.0156, 0.0005, '', '<p>Reversing a reaction inverts K: K&prime; = 1/64 = <b>0.0156</b>.</p>'),
    mk('ce-015', 2, 'changing the equation', 'For N<sub>2</sub> + 3H<sub>2</sub> &#8652; 2NH<sub>3</sub> the constant is K. For &frac12;N<sub>2</sub> + 3/2 H<sub>2</sub> &#8652; NH<sub>3</sub> at the same temperature it is', '&radic;K', ['K/2', '2K', 'K<sup>2</sup>'], '<p>Multiplying all coefficients by n raises K to the power n. Here n = 1/2, so K&prime; = K<sup>1/2</sup>.</p>'),
    nat('ce-016', 2, 'K<sub>p</sub> and K<sub>c</sub>', 'For N<sub>2</sub>O<sub>4</sub>(g) &#8652; 2NO<sub>2</sub>(g), K<sub>c</sub> = 0.040 mol L<sup>-1</sup> at 400 K. Find K<sub>p</sub> in atm. (R = 0.0821 L atm K<sup>-1</sup> mol<sup>-1</sup>)', 1.31, 0.02, 'atm', '<p>K<sub>p</sub> = K<sub>c</sub>(RT)<sup>&Delta;n<sub>g</sub></sup>, with &Delta;n<sub>g</sub> = 2 - 1 = 1.</p><p>K<sub>p</sub> = 0.040 &times; 0.0821 &times; 400 = <b>1.31 atm</b>.</p>'),
    mk('ce-017', 2, 'reaction quotient', 'For H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI, K<sub>c</sub> = 50. A mixture has [H<sub>2</sub>] = [I<sub>2</sub>] = 0.20 and [HI] = 1.2 mol L<sup>-1</sup>. The mixture', 'is not at equilibrium and moves forward', ['is not at equilibrium and moves backward', 'is at equilibrium', 'has Q = 6'], '<p>Q = (1.2)<sup>2</sup>/(0.20 &times; 0.20) = 1.44/0.04 = 36. Since Q (36) &lt; K (50), more HI must form: the net reaction goes forward.</p>'),
    nat('ce-018', 2, 'degree of dissociation', 'PCl<sub>5</sub>(g) &#8652; PCl<sub>3</sub>(g) + Cl<sub>2</sub>(g) is 40% dissociated at a total pressure of 2.1 atm. Find K<sub>p</sub> in atm.', 0.40, 0.01, 'atm', '<p>Start with 1 mol PCl<sub>5</sub>. At equilibrium: PCl<sub>5</sub> 0.6, PCl<sub>3</sub> 0.4, Cl<sub>2</sub> 0.4; total 1.4 mol.</p><p>Partial pressures: 0.6/1.4 &times; 2.1 = 0.9; 0.4/1.4 &times; 2.1 = 0.6 each.</p><p>K<sub>p</sub> = (0.6 &times; 0.6)/0.9 = <b>0.40 atm</b>. (Formula: &alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>) = 0.16 &times; 2.1/0.84.)</p>'),
    nat('ce-019', 2, 'vapour density', 'The theoretical vapour density of PCl<sub>5</sub> is 104.25. At a certain temperature the observed vapour density of its equilibrium mixture is 80.19. Find the degree of dissociation.', 0.30, 0.01, '', '<p>For PCl<sub>5</sub> &#8652; PCl<sub>3</sub> + Cl<sub>2</sub>, one mole gives 1 + &alpha; moles, so the density falls: D/d = 1 + &alpha;.</p><p>&alpha; = (D - d)/d = (104.25 - 80.19)/80.19 = <b>0.30</b>.</p>', 'Dividing by D instead of d gives 0.23.'),
    mk('ce-020', 2, 'heterogeneous equilibrium', 'CaCO<sub>3</sub>(s) is in equilibrium with CaO(s) and CO<sub>2</sub>(g) in a closed vessel at constant temperature. If more CaCO<sub>3</sub>(s) is added, the pressure of CO<sub>2</sub>', 'does not change', ['increases', 'decreases', 'first falls and then rises'], '<p>K<sub>p</sub> = p(CO<sub>2</sub>), and K<sub>p</sub> depends only on temperature. Pure solids do not appear in K, so adding more solid does not shift the equilibrium. p(CO<sub>2</sub>) stays the same.</p>', 'The famous misconception: adding any reactant shifts the equilibrium; not a solid.'),
    mk('ce-021', 2, 'Le Chatelier principle', 'In N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g) at equilibrium, extra H<sub>2</sub> is added at constant volume and temperature. Afterwards', 'more NH<sub>3</sub> is formed and K is unchanged', ['more NH<sub>3</sub> is formed and K increases', 'NH<sub>3</sub> decreases and K decreases', 'nothing changes, as the system is at equilibrium'], '<p>Adding H<sub>2</sub> makes Q &lt; K, so the net reaction moves forward until Q = K again. K itself depends only on temperature.</p>'),
    mk('ce-022', 2, 'effect of volume', 'For PCl<sub>5</sub>(g) &#8652; PCl<sub>3</sub>(g) + Cl<sub>2</sub>(g), when the volume of the vessel is reduced at constant temperature, the degree of dissociation', 'decreases', ['increases', 'stays the same', 'becomes zero'], '<p>Less volume means higher pressure. The system moves to the side with fewer gas moles: 1 mol (PCl<sub>5</sub>) against 2 mol. So the equilibrium shifts back and &alpha; falls.</p>'),
    nat('ce-023', 2, 'ICE table', '0.20 mol L<sup>-1</sup> N<sub>2</sub>O<sub>4</sub> is placed in a vessel. At equilibrium [NO<sub>2</sub>] = 0.080 mol L<sup>-1</sup>. Find K<sub>c</sub> for N<sub>2</sub>O<sub>4</sub> &#8652; 2NO<sub>2</sub> in mol L<sup>-1</sup>.', 0.040, 0.001, 'mol L<sup>-1</sup>', '<p>[NO<sub>2</sub>] = 2x = 0.080, so x = 0.040. [N<sub>2</sub>O<sub>4</sub>] = 0.20 - 0.040 = 0.16.</p><p>K<sub>c</sub> = (0.080)<sup>2</sup>/0.16 = 0.0064/0.16 = <b>0.040</b>.</p>', 'Using 0.080 as the amount of N<sub>2</sub>O<sub>4</sub> that reacted.'),
    nat('ce-024', 2, 'ICE table', 'One mole each of H<sub>2</sub> and I<sub>2</sub> are heated in a 1 L vessel. K<sub>c</sub> for H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI is 4.0 at that temperature. Find the amount of HI (mol) at equilibrium.', 1.0, 0.02, 'mol', '<p>Let x mol of each react: [HI] = 2x, [H<sub>2</sub>] = [I<sub>2</sub>] = 1 - x.</p><p>(2x)<sup>2</sup>/(1 - x)<sup>2</sup> = 4, so 2x/(1 - x) = 2 and x = 0.5. HI = 2x = <b>1.0 mol</b>.</p>'),
    mk('ce-025', 2, 'Haber process', 'The formation of NH<sub>3</sub> is exothermic. A moderate temperature (about 700 K) is used in industry because', 'low temperature favours yield but makes the reaction too slow', ['high temperature increases K', 'a catalyst works only at high temperature', 'NH<sub>3</sub> is decomposed at 300 K'], '<p>A compromise: lowering temperature raises K and the yield, but the rate becomes too slow. About 700 K with an iron catalyst gives a fair rate and acceptable yield.</p>'),
    mk('ce-026', 2, 'units of K<sub>p</sub>', 'The unit of K<sub>p</sub> for N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g), pressures in atm, is', 'atm<sup>-2</sup>', ['atm<sup>2</sup>', 'atm', 'no unit'], '<p>K<sub>p</sub> = p(NH<sub>3</sub>)<sup>2</sup>/(p(N<sub>2</sub>)p(H<sub>2</sub>)<sup>3</sup>) has units atm<sup>2-4</sup> = atm<sup>-2</sup>.</p>'),
    nat('ce-027', 2, 'heterogeneous equilibrium', 'Solid NH<sub>4</sub>HS decomposes: NH<sub>4</sub>HS(s) &#8652; NH<sub>3</sub>(g) + H<sub>2</sub>S(g). At equilibrium in a vessel the total pressure is 0.80 atm. Find K<sub>p</sub> in atm<sup>2</sup>.', 0.16, 0.005, 'atm<sup>2</sup>', '<p>NH<sub>3</sub> and H<sub>2</sub>S are formed in equal amounts, so each has a partial pressure of 0.40 atm.</p><p>K<sub>p</sub> = 0.40 &times; 0.40 = <b>0.16 atm<sup>2</sup></b>.</p>', 'Using 0.80 for each gas gives 0.64.'),
    nat('ce-028', 2, 'heterogeneous equilibrium', 'Ammonium carbamate decomposes: NH<sub>2</sub>COONH<sub>4</sub>(s) &#8652; 2NH<sub>3</sub>(g) + CO<sub>2</sub>(g). At equilibrium the total pressure is 0.90 atm. Find K<sub>p</sub> in atm<sup>3</sup>.', 0.108, 0.002, 'atm<sup>3</sup>', '<p>The gases are in the ratio 2 : 1, so p(NH<sub>3</sub>) = 2/3 &times; 0.90 = 0.60 atm and p(CO<sub>2</sub>) = 0.30 atm.</p><p>K<sub>p</sub> = (0.60)<sup>2</sup>(0.30) = <b>0.108 atm<sup>3</sup></b>.</p>'),
    nat('ce-029', 2, 'combining equilibria', 'A &#8652; B has K = 4 and B &#8652; C has K = 5 at the same temperature. Find K for A &#8652; C.', 20, 0, '', '<p>Adding two reactions multiplies their constants: K = 4 &times; 5 = <b>20</b>.</p>'),
    asr('ce-030', 2, 'catalyst', 'A catalyst does not change the equilibrium constant of a reaction.', 'A catalyst lowers the activation energy of the forward and the backward reactions equally.', 0, '<p>Both are true. If both rate constants rise by the same factor, their ratio K = k<sub>f</sub>/k<sub>b</sub> is unchanged. R explains A.</p>'),
    asr('ce-031', 2, 'effect of pressure', 'Increasing the pressure on PCl<sub>5</sub> &#8652; PCl<sub>3</sub> + Cl<sub>2</sub> at equilibrium decreases the amount of PCl<sub>3</sub>.', 'The backward reaction produces fewer moles of gas than the forward reaction.', 0, '<p>Both are true. Higher pressure favours the side with fewer moles of gas (PCl<sub>5</sub>, 1 mol against 2 mol), so PCl<sub>3</sub> falls. R is the reason.</p>'),
    stm('ce-032', 2, 'K<sub>c</sub> and units', 'K<sub>c</sub> of H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI has no unit.', 'For this reaction K<sub>p</sub> = K<sub>c</sub>.', 0, '<p>&Delta;n<sub>g</sub> = 0, so units cancel and (RT)<sup>0</sup> = 1. Both correct.</p>'),

    // ---------- Level 3 ----------
    nat('ce-033', 3, 'degree of dissociation', 'PCl<sub>5</sub> is 50% dissociated at 1.0 atm total pressure. Find K<sub>p</sub> in atm.', 0.333, 0.005, 'atm', '<p>K<sub>p</sub> = &alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>) = (0.25)(1.0)/(0.75) = <b>0.333 atm</b>.</p>'),
    nat('ce-034', 3, 'degree of dissociation', 'N<sub>2</sub>O<sub>4</sub> &#8652; 2NO<sub>2</sub> is 20% dissociated at 1.0 atm total pressure. Find K<sub>p</sub> in atm.', 0.167, 0.003, 'atm', '<p>One mole N<sub>2</sub>O<sub>4</sub> gives 1 - &alpha; and 2&alpha; moles, total 1 + &alpha;.</p><p>K<sub>p</sub> = 4&alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>) = 4(0.04)(1)/(0.96) = <b>0.167 atm</b>.</p>', 'The factor 4 comes from the 2NO<sub>2</sub> squared.'),
    nat('ce-035', 3, 'degree of dissociation', 'With K<sub>p</sub> = 0.1667 atm for N<sub>2</sub>O<sub>4</sub> &#8652; 2NO<sub>2</sub>, find the degree of dissociation at a total pressure of 4.0 atm.', 0.10, 0.005, '', '<p>K<sub>p</sub> = 4&alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>). So &alpha;<sup>2</sup>/(1 - &alpha;<sup>2</sup>) = 0.1667/16 = 0.01042, giving &alpha;<sup>2</sup> = 0.0103 and &alpha; = <b>0.10</b>.</p><p>At 1 atm it was 0.20: four times the pressure halves &alpha; (&alpha; &prop; P<sup>-1/2</sup> when &alpha; is small).</p>'),
    nat('ce-036', 3, 'vapour density', 'N<sub>2</sub>O<sub>4</sub> (M = 92) partly dissociates into NO<sub>2</sub>. The average molar mass of the equilibrium mixture is 76.7 g mol<sup>-1</sup>. Find the degree of dissociation.', 0.20, 0.01, '', '<p>Moles after dissociation = 1 + &alpha; for each mole. Since mass is conserved, M<sub>mix</sub> = M/(1 + &alpha;).</p><p>1 + &alpha; = 92/76.7 = 1.20, so &alpha; = <b>0.20</b>.</p>', 'Mixed with the mole concept.'),
    nat('ce-037', 3, 'van&rsquo;t Hoff equation', 'For an endothermic reaction &Delta;H = +50 kJ mol<sup>-1</sup>. By what factor does K increase when the temperature rises from 300 K to 310 K? (R = 8.314; assume &Delta;H is constant)', 1.91, 0.03, '', '<p>ln(K<sub>2</sub>/K<sub>1</sub>) = (&Delta;H/R)(1/T<sub>1</sub> - 1/T<sub>2</sub>) = (50 000/8.314)(1/300 - 1/310) = 6014 &times; 1.075 &times; 10<sup>-4</sup> = 0.647.</p><p>K<sub>2</sub>/K<sub>1</sub> = e<sup>0.647</sup> = <b>1.91</b>.</p>'),
    nat('ce-038', 3, 'van&rsquo;t Hoff equation', 'For a reaction, K = 200 at 300 K and K = 3.63 at 400 K. Find &Delta;H in kJ mol<sup>-1</sup>. (R = 8.314)', -40, 0.6, 'kJ mol<sup>-1</sup>', '<p>ln(K<sub>2</sub>/K<sub>1</sub>) = ln(3.63/200) = -4.009. (1/T<sub>1</sub> - 1/T<sub>2</sub>) = 1/300 - 1/400 = 8.33 &times; 10<sup>-4</sup>.</p><p>&Delta;H = R &times; ln(K<sub>2</sub>/K<sub>1</sub>)/(1/T<sub>1</sub> - 1/T<sub>2</sub>) = 8.314 &times; (-4.009)/(8.33 &times; 10<sup>-4</sup>) = -40 000 J = <b>-40 kJ mol<sup>-1</sup></b>. K falls on heating, so the reaction is exothermic.</p>'),
    nat('ce-039', 3, 'mixed: thermodynamics', 'At 300 K the equilibrium constant of a reaction is 0.10. Find &Delta;G&deg; in kJ mol<sup>-1</sup>. (R = 8.314; log 0.1 = -1)', 5.74, 0.05, 'kJ mol<sup>-1</sup>', '<p>&Delta;G&deg; = -2.303RT log K = -2.303 &times; 8.314 &times; 300 &times; (-1) = +5743 J = <b>+5.74 kJ mol<sup>-1</sup></b>.</p><p>K &lt; 1 gives positive &Delta;G&deg;.</p>', 'Mixed with chemical thermodynamics.'),
    nat('ce-040', 3, 'mixed: thermodynamics', 'The standard Gibbs energy change of a reaction at 298 K is -17.1 kJ mol<sup>-1</sup>. Find log<sub>10</sub> K. (2.303RT = 5.71 kJ mol<sup>-1</sup> at 298 K)', 3.0, 0.02, '', '<p>&Delta;G&deg; = -2.303RT log K, so log K = 17.1/5.71 = <b>3.0</b> and K &asymp; 10<sup>3</sup>.</p>', 'Mixed with chemical thermodynamics.'),
    nat('ce-041', 3, 'heterogeneous equilibrium', 'CuSO<sub>4</sub>&middot;5H<sub>2</sub>O(s) &#8652; CuSO<sub>4</sub>&middot;3H<sub>2</sub>O(s) + 2H<sub>2</sub>O(g). At equilibrium the vapour pressure of water is 0.010 atm. Find K<sub>p</sub> in units of 10<sup>-4</sup> atm<sup>2</sup>.', 1.0, 0.02, '10<sup>-4</sup> atm<sup>2</sup>', '<p>Only the gas appears: K<sub>p</sub> = p(H<sub>2</sub>O)<sup>2</sup> = (0.010)<sup>2</sup> = 1.0 &times; 10<sup>-4</sup> atm<sup>2</sup>. Answer <b>1.0</b>.</p>', 'The power is the coefficient 2.'),
    nat('ce-042', 3, 'ICE table', 'A(g) &#8652; B(g) + C(g) has K<sub>c</sub> = 0.50 mol L<sup>-1</sup>. Start with 1.0 mol L<sup>-1</sup> of A. Find [B] at equilibrium in mol L<sup>-1</sup>.', 0.50, 0.01, 'mol L<sup>-1</sup>', '<p>x<sup>2</sup>/(1 - x) = 0.50, so x<sup>2</sup> + 0.5x - 0.5 = 0. x = [-0.5 + &radic;(0.25 + 2)]/2 = (-0.5 + 1.5)/2 = <b>0.50</b>.</p>'),
    nat('ce-043', 3, 'ICE table', 'For H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI, K<sub>c</sub> = 49. Decomposition of pure HI gives the same equilibrium. What fraction of HI decomposes? (2HI &#8652; H<sub>2</sub> + I<sub>2</sub>)', 0.222, 0.005, '', '<p>For 2HI &#8652; H<sub>2</sub> + I<sub>2</sub>, K&prime; = 1/49. Start with 1 mol HI; &alpha; decomposes: H<sub>2</sub> = I<sub>2</sub> = &alpha;/2, HI = 1 - &alpha;.</p><p>(&alpha;/2)<sup>2</sup>/(1 - &alpha;)<sup>2</sup> = 1/49, so (&alpha;/2)/(1 - &alpha;) = 1/7 and 7&alpha; = 2 - 2&alpha;. &alpha; = 2/9 = <b>0.222</b>.</p>'),
    nat('ce-044', 3, 'ICE table', 'A(g) + B(g) &#8652; C(g) + D(g), K<sub>c</sub> = 4. One mole each of A and B are placed in a 1 L vessel. Find the moles of C at equilibrium.', 0.667, 0.01, 'mol', '<p>x<sup>2</sup>/(1 - x)<sup>2</sup> = 4 so x/(1 - x) = 2 and x = <b>2/3 = 0.667 mol</b>.</p>'),
    mk('ce-045', 3, 'inert gas', 'For N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g) at equilibrium, argon is added at <b>constant pressure</b>. The yield of NH<sub>3</sub>', 'decreases', ['increases', 'does not change', 'becomes zero'], '<p>At constant pressure the volume grows, so the partial pressures of all gases fall, like lowering the total pressure. The system shifts to the side with more gas moles (reactants: 4 mol against 2). NH<sub>3</sub> decreases.</p>', 'At constant volume, no shift. At constant pressure, argon acts like a lower pressure.'),
    mk('ce-046', 3, 'inert gas', 'For PCl<sub>5</sub> &#8652; PCl<sub>3</sub> + Cl<sub>2</sub> in a rigid vessel, helium is added. The degree of dissociation', 'stays the same, since the partial pressures are unchanged', ['increases, since total pressure increases', 'decreases, since total pressure increases', 'increases, since volume of gas increases'], '<p>Volume is fixed and He does not react, so each gas keeps its own moles per litre and partial pressure. Q is still equal to K, so nothing shifts.</p>', 'Total pressure rises, but the equilibrium depends on the partial pressures of the reacting gases.'),
    mk('ce-047', 3, 'temperature effect', 'For an exothermic reaction, a rise in temperature', 'decreases K and shifts the equilibrium backward', ['increases K and shifts it forward', 'does not change K but shifts it backward', 'increases the rate only of the backward reaction'], '<p>Heat is a product of an exothermic reaction; adding heat pushes the equilibrium back, so K falls. The rates of <i>both</i> reactions increase (the backward one more), so option D is also wrong.</p>'),
    mk('ce-048', 3, 'effect of removing a product', 'In the reaction CaCO<sub>3</sub>(s) &#8652; CaO(s) + CO<sub>2</sub>(g), the decomposition can be made complete by', 'heating in an open vessel so CO<sub>2</sub> escapes', ['heating in a closed vessel', 'increasing the pressure of CO<sub>2</sub>', 'adding more CaO'], '<p>Removing CO<sub>2</sub> keeps Q below K, so the reaction goes on to completion (limestone kilns work this way). In a closed vessel p(CO<sub>2</sub>) reaches K<sub>p</sub> and the reaction stops.</p>'),
    nat('ce-049', 3, 'mixed: mole concept', 'CaCO<sub>3</sub>(s) &#8652; CaO(s) + CO<sub>2</sub>(g) has K<sub>p</sub> = 0.821 atm at 1000 K. What is the minimum mass of CaCO<sub>3</sub> (g) that must be placed in a 10 L vessel (initially empty) at 1000 K for equilibrium to be established? (R = 0.0821 L atm K<sup>-1</sup> mol<sup>-1</sup>; CaCO<sub>3</sub> = 100 g mol<sup>-1</sup>)', 10, 0.2, 'g', '<p>At equilibrium p(CO<sub>2</sub>) = K<sub>p</sub> = 0.821 atm. Moles of CO<sub>2</sub> needed: n = PV/RT = 0.821 &times; 10/(0.0821 &times; 1000) = 0.100 mol.</p><p>Each mole of CO<sub>2</sub> comes from one mole of CaCO<sub>3</sub>: 0.100 mol &times; 100 g mol<sup>-1</sup> = <b>10 g</b>. Any less and all the solid decomposes before p reaches 0.821 atm.</p>', 'Mixed with the gas laws and the mole concept.'),
    asr('ce-050', 3, 'K<sub>p</sub> and K<sub>c</sub>', 'For H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI, K<sub>p</sub> equals K<sub>c</sub>.', 'The total pressure does not affect the position of equilibrium of this reaction.', 1, '<p>Both are true, but R is not the reason for A. K<sub>p</sub> = K<sub>c</sub> because &Delta;n<sub>g</sub> = 0. R is true for the same cause (equal moles of gas on both sides); one fact does not explain the other.</p>'),
    asr('ce-051', 3, 'K and pressure', 'The equilibrium constant of N<sub>2</sub> + 3H<sub>2</sub> &#8652; 2NH<sub>3</sub> increases when the pressure is increased.', 'By Le Chatelier&rsquo;s principle, an increase in pressure favours the formation of NH<sub>3</sub>.', 3, '<p>A is false: K depends only on temperature. R is true: the position of equilibrium shifts to the side with fewer moles, but K stays the same because Q recovers to the same K.</p>', 'Position of equilibrium vs value of K.'),
    stm('ce-052', 3, 'effect of temperature', 'The K of an endothermic reaction increases with temperature.', 'Increasing pressure always increases K for a gas-phase reaction.', 1, '<p>I is correct (van&rsquo;t Hoff). II is incorrect: K does not depend on pressure.</p>'),
    stm('ce-053', 3, 'catalyst', 'A catalyst increases the equilibrium yield of products.', 'A catalyst helps the equilibrium to be reached faster.', 2, '<p>I is false: K and the equilibrium composition are not changed by a catalyst. II is true: both rates rise, so equilibrium is reached sooner.</p>'),
    msq('ce-054', 3, 'Le Chatelier principle', 'For N<sub>2</sub> + 3H<sub>2</sub> &#8652; 2NH<sub>3</sub> (&Delta;H &lt; 0), which changes shift the equilibrium towards NH<sub>3</sub>?', ['Increasing the pressure by reducing the volume', 'Removing NH<sub>3</sub> as it forms', 'Adding a catalyst', 'Lowering the temperature'], [0, 1, 3], '<p>A: fewer gas moles on the right. B: Q falls below K. D: exothermic reaction favoured by cold. A catalyst changes only the rate.</p>'),
    msq('ce-055', 3, 'equilibrium constant', 'Which of the following do <b>not</b> change the value of K<sub>c</sub> of a reaction?', ['Temperature', 'Pressure', 'A catalyst', 'Initial concentrations'], [1, 2, 3], '<p>K<sub>c</sub> changes only with temperature. Pressure, catalyst and starting concentrations leave it alone.</p>'),
    mat('ce-056', 3, 'Le Chatelier principle', 'm1', 'Match List I with List II. Choose the correct code.', 'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-p, C-s, D-r', 'A-r, B-p, C-q, D-s'], '<p>A: compressing shifts the equilibrium towards the side with fewer moles, NH<sub>3</sub> (q). B: heating favours the endothermic backward direction (p). C: a catalyst gives the same composition sooner (r). D: argon at constant volume leaves all partial pressures unchanged (s).</p>'),
    mat('ce-057', 3, 'units of K', 'm2', 'Match List I with List II. Choose the correct code.', 'A-s, B-q, C-p, D-r', ['A-q, B-s, C-p, D-r', 'A-s, B-q, C-r, D-p', 'A-p, B-q, C-s, D-r'], '<p>Unit = (mol L<sup>-1</sup>)<sup>&Delta;n</sup>. A: &Delta;n = -2, L<sup>2</sup> mol<sup>-2</sup>. B: &Delta;n = +1, mol L<sup>-1</sup>. C: &Delta;n = 0, none. D: &Delta;n = -1, L mol<sup>-1</sup>.</p>'),
    mat('ce-058', 3, 'reaction quotient', 'm3', 'Match List I with List II. Choose the correct code.', 'A-r, B-p, C-q, D-s', ['A-p, B-r, C-q, D-s', 'A-r, B-p, C-s, D-q', 'A-q, B-p, C-r, D-s'], '<p>Q &lt; K: forward (r). Q &gt; K: backward (p). Q = K: equilibrium (q). With no products at the start, Q = 0, so only the forward reaction can go (s).</p>'),
    mat('ce-059', 3, 'K<sub>p</sub> expressions', 'm4', 'Match List I with List II. Choose the correct code.', 'A-r, B-p, C-s, D-q', ['A-p, B-r, C-s, D-q', 'A-r, B-p, C-q, D-s', 'A-s, B-p, C-r, D-q'], '<p>Solids are left out. A: only CO<sub>2</sub> (r). B: NH<sub>3</sub> &times; H<sub>2</sub>S (p). C: products over reactants squared (s). D: C(s) omitted: p(CO)<sup>2</sup>/p(CO<sub>2</sub>) (q).</p>'),

    // ---------- Level 4 ----------
    PN('ce-060', 4, 'degree of dissociation', 'p1', 'Find the degree of dissociation of N<sub>2</sub>O<sub>4</sub>.', 0.20, 0.01, '', '<p>At constant volume and temperature, pressure is proportional to moles. N<sub>2</sub>O<sub>4</sub>: 1.00 - p; NO<sub>2</sub>: 2p. Total = 1.00 + p = 1.20, so p = 0.20 atm.</p><p>&alpha; = 0.20/1.00 = <b>0.20</b>.</p>'),
    PN('ce-061', 4, 'K<sub>p</sub>', 'p1', 'Find K<sub>p</sub> in atm.', 0.20, 0.005, 'atm', '<p>p(N<sub>2</sub>O<sub>4</sub>) = 1.00 - 0.20 = 0.80 atm; p(NO<sub>2</sub>) = 0.40 atm.</p><p>K<sub>p</sub> = (0.40)<sup>2</sup>/0.80 = <b>0.20 atm</b>.</p>', 'Do not use the formula 4&alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>) with the initial pressure in place of the total pressure at equilibrium.'),
    P('ce-062', 4, 'Le Chatelier principle', 'p1', 'The vessel is cooled to 300 K. The brown colour of the gas', 'fades, because the endothermic forward reaction is disfavoured at lower temperature', ['deepens, because cooling raises K', 'stays the same, since the volume is fixed', 'fades, because cooling shifts the reaction to the side with more gas moles'], '<p>The forward reaction (making brown NO<sub>2</sub>) is endothermic. Cooling favours the exothermic reverse, giving colourless N<sub>2</sub>O<sub>4</sub>. K decreases on cooling.</p>'),
    P('ce-063', 4, 'Haber process', 'p2', 'A pressure as high as 200 atm is used because', 'there are fewer gas moles on the product side, so pressure raises the yield', ['it increases the value of K', 'it lowers the activation energy', 'it makes the reaction exothermic'], '<p>4 mol of gas become 2 mol, so by Le Chatelier a higher pressure favours NH<sub>3</sub>. K itself is unchanged by pressure, and a catalyst, not pressure, lowers the activation energy.</p>'),
    P('ce-064', 4, 'Haber process', 'p2', 'Cooling the mixture to liquefy NH<sub>3</sub> and removing it', 'keeps Q below K so the reaction keeps going forward', ['raises K', 'lowers the pressure and so lowers the yield', 'acts as a catalyst'], '<p>NH<sub>3</sub> liquefies at a far higher temperature than N<sub>2</sub> and H<sub>2</sub>. Removing it lowers its concentration, so Q &lt; K and more NH<sub>3</sub> is made.</p>'),
    P('ce-065', 4, 'Haber process', 'p2', 'Compared with the same reaction run at 500 K, the value of K at 700 K is', 'smaller, because the forward reaction is exothermic', ['larger, because the rate is faster', 'the same, since the catalyst is present', 'larger, because the pressure is higher'], '<p>For an exothermic reaction, K falls as temperature rises. The rate is higher at 700 K, but that is a rate effect, not an equilibrium effect.</p>'),
    P('ce-066', 4, 'reaction quotient', 'p3', 'Just after the volume is halved, the reaction quotient Q (in mol L<sup>-1</sup>) and the direction of change are', '0.20, backward', ['0.10, no change', '0.20, forward', '0.05, forward'], '<p>K<sub>c</sub> = (0.20)(0.20)/0.40 = 0.10. After halving the volume all concentrations double: 0.80, 0.40, 0.40.</p><p>Q = (0.40)(0.40)/0.80 = 0.20 &gt; K, so the net reaction is <b>backward</b>.</p>'),
    PN('ce-067', 4, 'ICE table', 'p3', 'Find the new equilibrium concentration of PCl<sub>3</sub> in mol L<sup>-1</sup>.', 0.30, 0.01, 'mol L<sup>-1</sup>', '<p>Start from the doubled values: PCl<sub>5</sub> 0.80, PCl<sub>3</sub> 0.40, Cl<sub>2</sub> 0.40. Let x of PCl<sub>3</sub> and Cl<sub>2</sub> recombine.</p><p>(0.40 - x)<sup>2</sup>/(0.80 + x) = 0.10 &rArr; x<sup>2</sup> - 0.9x + 0.08 = 0 &rArr; x = 0.10 (the other root, 0.8, is impossible).</p><p>[PCl<sub>3</sub>] = 0.40 - 0.10 = <b>0.30 mol L<sup>-1</sup></b>. It lies between the old 0.20 and the doubled 0.40.</p>'),
    P('ce-068', 4, 'equilibrium constant', 'p3', 'The value of K<sub>c</sub> at the new equilibrium is', '0.10 mol L<sup>-1</sup>, the same as before', ['0.20 mol L<sup>-1</sup>', '0.05 mol L<sup>-1</sup>', 'greater than 0.10 mol L<sup>-1</sup>, because pressure increased'], '<p>Temperature is constant, so K<sub>c</sub> does not change. Check: (0.30)(0.30)/0.90 = 0.10.</p>'),
    nat('ce-069', 4, 'K<sub>p</sub> from partial pressures', 'Pure N<sub>2</sub>O<sub>4</sub> at an initial pressure of 0.50 atm is kept in a rigid vessel. At equilibrium the total pressure is 0.75 atm. Find K<sub>p</sub> for N<sub>2</sub>O<sub>4</sub> &#8652; 2NO<sub>2</sub> in atm.', 1.0, 0.02, 'atm', '<p>Let N<sub>2</sub>O<sub>4</sub> lose x atm: pressures 0.50 - x and 2x. Total = 0.50 + x = 0.75, so x = 0.25.</p><p>p(N<sub>2</sub>O<sub>4</sub>) = 0.25, p(NO<sub>2</sub>) = 0.50. K<sub>p</sub> = 0.25/0.25 = <b>1.0 atm</b>.</p>'),
    nat('ce-070', 4, 'mole fractions', 'One mole of N<sub>2</sub> and three moles of H<sub>2</sub> react at a total pressure of 10 atm. At equilibrium NH<sub>3</sub> is 20% by volume. Find K<sub>p</sub> in units of 10<sup>-3</sup> atm<sup>-2</sup>.', 9.26, 0.05, '10<sup>-3</sup> atm<sup>-2</sup>', '<p>If 2x mol NH<sub>3</sub> form: N<sub>2</sub> = 1 - x, H<sub>2</sub> = 3 - 3x, NH<sub>3</sub> = 2x, total 4 - 2x. 2x/(4 - 2x) = 0.2 gives x = 1/3.</p><p>Mole fractions: NH<sub>3</sub> 0.20, N<sub>2</sub> 0.20, H<sub>2</sub> 0.60. Partial pressures (&times;10): 2, 2, 6 atm.</p><p>K<sub>p</sub> = 2<sup>2</sup>/(2 &times; 6<sup>3</sup>) = 4/432 = 9.26 &times; 10<sup>-3</sup> atm<sup>-2</sup>. Answer <b>9.26</b>.</p>'),
    nat('ce-071', 4, 'van&rsquo;t Hoff equation', 'A plot of log<sub>10</sub> K against 1/T for a reaction is a straight line of slope -2610 K. Find &Delta;H in kJ mol<sup>-1</sup>. (R = 8.314)', 50, 0.5, 'kJ mol<sup>-1</sup>', '<p>log K = -&Delta;H/(2.303R) &middot; (1/T) + constant, so slope = -&Delta;H/(2.303R).</p><p>&Delta;H = 2.303 &times; 8.314 &times; 2610 = 49 970 J &asymp; <b>+50 kJ mol<sup>-1</sup></b>. A negative slope means endothermic.</p>', 'If the plot were ln K the slope would be -&Delta;H/R; using the log<sub>10</sub> slope needs the factor 2.303.'),
    nat('ce-072', 4, 'simultaneous equilibria', 'Solid NH<sub>4</sub>I dissociates: NH<sub>4</sub>I(s) &#8652; NH<sub>3</sub>(g) + HI(g), and some HI also dissociates: 2HI(g) &#8652; H<sub>2</sub>(g) + I<sub>2</sub>(g). At equilibrium p(H<sub>2</sub>) = 0.10 atm and the total pressure is 1.00 atm. Find K<sub>p</sub> for the first reaction in atm<sup>2</sup>.', 0.15, 0.005, 'atm<sup>2</sup>', '<p>H<sub>2</sub> = I<sub>2</sub> = 0.10 atm, which used 0.20 atm of HI. Let p(NH<sub>3</sub>) = y: HI = y - 0.20 (NH<sub>3</sub> = total HI formed).</p><p>Total = y + (y - 0.20) + 0.10 + 0.10 = 2y = 1.00, so y = 0.50. HI = 0.30.</p><p>K<sub>p</sub>(1) = 0.50 &times; 0.30 = <b>0.15 atm<sup>2</sup></b>. (K<sub>p</sub>(2) = 0.01/0.09 = 0.111.)</p>', 'NH<sub>3</sub> equals all the HI formed, not the HI left.'),
    mk('ce-073', 4, 'unit trap', 'A student uses concentrations in mol L<sup>-1</sup> in K<sub>c</sub> for N<sub>2</sub> + 3H<sub>2</sub> &#8652; 2NH<sub>3</sub> and finds K<sub>c</sub> = 4.0 L<sup>2</sup> mol<sup>-2</sup>. Which is correct about K<sub>p</sub> at 500 K? (R = 0.0821 L atm K<sup>-1</sup> mol<sup>-1</sup>)', 'K<sub>p</sub> = 4.0/(41.05)<sup>2</sup> atm<sup>-2</sup> = 2.4 &times; 10<sup>-3</sup> atm<sup>-2</sup>', ['K<sub>p</sub> = 4.0 &times; (41.05)<sup>2</sup> atm<sup>-2</sup>', 'K<sub>p</sub> = 4.0 atm<sup>-2</sup>', 'K<sub>p</sub> = 4.0/41.05 atm<sup>-1</sup>'], '<p>&Delta;n<sub>g</sub> = 2 - 4 = -2, so K<sub>p</sub> = K<sub>c</sub>(RT)<sup>-2</sup>. RT = 0.0821 &times; 500 = 41.05, so K<sub>p</sub> = 4.0/1685 = 2.4 &times; 10<sup>-3</sup> atm<sup>-2</sup>.</p>', 'A negative &Delta;n<sub>g</sub> makes K<sub>p</sub> smaller than K<sub>c</sub> numerically.'),
    mk('ce-074', 4, 'mole fractions', 'In a gas reaction, K<sub>p</sub> = K<sub>x</sub>P<sup>&Delta;n<sub>g</sub></sup>, where K<sub>x</sub> uses mole fractions. For N<sub>2</sub>O<sub>4</sub> &#8652; 2NO<sub>2</sub>, if K<sub>p</sub> is fixed, increasing the total pressure P', 'decreases K<sub>x</sub>', ['increases K<sub>x</sub>', 'leaves K<sub>x</sub> unchanged', 'increases K<sub>p</sub>'], '<p>&Delta;n<sub>g</sub> = +1, so K<sub>x</sub> = K<sub>p</sub>/P. With K<sub>p</sub> constant, a larger P lowers K<sub>x</sub>: less NO<sub>2</sub> fraction, i.e. a shift backward.</p>'),
    msq('ce-075', 4, 'K<sub>p</sub> and K<sub>c</sub>', 'For 2SO<sub>2</sub>(g) + O<sub>2</sub>(g) &#8652; 2SO<sub>3</sub>(g) at 300 K (R = 0.0821 L atm K<sup>-1</sup> mol<sup>-1</sup>), which statements are correct?', ['K<sub>p</sub> = K<sub>c</sub>/(RT)', 'K<sub>c</sub> has units L mol<sup>-1</sup>', 'The numerical value of K<sub>p</sub> is less than that of K<sub>c</sub>', 'K increases if the temperature is raised (the reaction is exothermic)'], [0, 1, 2], '<p>&Delta;n<sub>g</sub> = -1, so K<sub>p</sub> = K<sub>c</sub>(RT)<sup>-1</sup>. Units of K<sub>c</sub>: (mol L<sup>-1</sup>)<sup>-1</sup>. RT = 24.6 &gt; 1, so K<sub>p</sub> &lt; K<sub>c</sub> numerically. Exothermic: K falls on heating, so D is false.</p>'),
    msq('ce-076', 4, 'degree of dissociation', 'For PCl<sub>5</sub>(g) &#8652; PCl<sub>3</sub>(g) + Cl<sub>2</sub>(g), &Delta;H = +93 kJ mol<sup>-1</sup>. The degree of dissociation increases on', ['heating at constant volume', 'compressing the vessel', 'adding helium at constant pressure', 'adding Cl<sub>2</sub> at constant volume'], [0, 2], '<p>Heating favours the endothermic forward reaction. Helium at constant pressure expands the gas and lowers partial pressures, favouring more moles (forward). Compression and extra Cl<sub>2</sub> both push backward.</p>'),
    msq('ce-077', 4, 'unit analysis', 'For which reactions does K<sub>c</sub> have the unit L<sup>2</sup> mol<sup>-2</sup>?', ['N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g)', 'CO(g) + 2H<sub>2</sub>(g) &#8652; CH<sub>3</sub>OH(g)', '2SO<sub>2</sub>(g) + O<sub>2</sub>(g) &#8652; 2SO<sub>3</sub>(g)', 'N<sub>2</sub>O<sub>4</sub>(g) &#8652; 2NO<sub>2</sub>(g)'], [0, 1], '<p>The unit is (mol L<sup>-1</sup>)<sup>&Delta;n</sup>, so we need &Delta;n = -2. A: 2 - 4 = -2. B: 1 - 3 = -2. C: -1. D: +1.</p>'),
    asr('ce-078', 4, 'degree of dissociation', 'The degree of dissociation of N<sub>2</sub>O<sub>4</sub> falls as the total pressure rises at constant temperature.', 'K<sub>p</sub> = 4&alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>) is constant at a given temperature.', 0, '<p>If P rises with K<sub>p</sub> fixed, &alpha;<sup>2</sup>/(1 - &alpha;<sup>2</sup>) must fall, so &alpha; falls. R gives the relation that explains A.</p>'),
    asr('ce-079', 4, 'catalyst', 'Adding a catalyst to a system at equilibrium does not change the amounts of reactants and products present.', 'A catalyst speeds up the forward reaction but not the backward reaction.', 2, '<p>A is true: K and the composition are unchanged. R is false: a catalyst lowers the activation energy of both directions equally, so both rates rise by the same factor.</p>', 'A catalyst cannot favour one direction.'),
    stm('ce-080', 4, 'inert gas', 'Argon is added at constant volume to PCl<sub>5</sub> &#8652; PCl<sub>3</sub> + Cl<sub>2</sub> at equilibrium. The degree of dissociation decreases.', 'Argon is added at constant volume, so the partial pressures of the reacting gases are not changed.', 2, '<p>I is wrong: nothing shifts at constant volume. II is right.</p>'),
    stm('ce-081', 4, 'inert gas', 'Argon at constant volume added to N<sub>2</sub> + 3H<sub>2</sub> &#8652; 2NH<sub>3</sub> shifts the equilibrium forward.', 'Argon at constant volume reduces the partial pressure of each reacting gas.', 3, '<p>Both are wrong: argon at constant volume leaves the moles per litre and the partial pressures of N<sub>2</sub>, H<sub>2</sub> and NH<sub>3</sub> unchanged; only the total pressure rises. Nothing shifts.</p>'),
    { id: 'ce-082', type: 'mcq', level: 4, format: 'statements', exams: EX[4], sub: 'equilibrium constants',
      q: '<p>Consider: (i) K<sub>p</sub> = K<sub>c</sub>(RT)<sup>&Delta;n<sub>g</sub></sup>; (ii) at equilibrium &Delta;G = 0; (iii) &Delta;G&deg; = 0 at equilibrium for every reaction; (iv) a catalyst changes the time taken to reach equilibrium. How many are correct?</p>',
      options: ['One', 'Two', 'Three', 'Four'], answer: 2,
      sol: '<p>(i) True. (ii) True: no net drive remains. (iii) False: &Delta;G&deg; = -RT ln K is zero only when K = 1; &Delta;G&deg; refers to the standard state, not to the equilibrium mixture. (iv) True: it changes the rate, not the position. Three are correct.</p>', trap: '&Delta;G and &Delta;G&deg; are different things.' },

    // ---------- Level 5 ----------
    nat('ce-083', 5, 'compression of an equilibrium', 'Pure N<sub>2</sub>O<sub>4</sub> at an initial pressure of 0.50 atm reaches equilibrium in a rigid vessel at constant T: total pressure 0.75 atm and K<sub>p</sub> = 1.0 atm. The vessel volume is now halved at constant T. Find the new total pressure in atm at equilibrium.', 1.39, 0.02, 'atm', '<p>Just after compression the partial pressures double: N<sub>2</sub>O<sub>4</sub> 0.50, NO<sub>2</sub> 1.00. Q = 1.00/0.50 = 2.0 &gt; K<sub>p</sub> = 1.0, so the reaction goes backward.</p><p>Let 2y atm of NO<sub>2</sub> turn into y atm of N<sub>2</sub>O<sub>4</sub>: (1.00 - 2y)<sup>2</sup>/(0.50 + y) = 1. This gives 4y<sup>2</sup> - 5y + 0.5 = 0, y = (5 - &radic;17)/8 = 0.1096.</p><p>Total = 1.50 - y = <b>1.39 atm</b> (less than the doubled 1.50 atm, as the shift reduces gas moles).</p>'),
    nat('ce-084', 5, 'simultaneous equilibria', 'In a closed vessel NH<sub>4</sub>I(s) &#8652; NH<sub>3</sub> + HI and 2HI &#8652; H<sub>2</sub> + I<sub>2</sub> are both at equilibrium. The partial pressure of NH<sub>3</sub> is 0.50 atm and K<sub>p</sub> for 2HI &#8652; H<sub>2</sub> + I<sub>2</sub> is 1/9 (about 0.111). Find the partial pressure of HI in atm.', 0.30, 0.01, 'atm', '<p>Let p(H<sub>2</sub>) = p(I<sub>2</sub>) = z. HI used = 2z, so p(HI) = 0.50 - 2z.</p><p>z<sup>2</sup>/(0.50 - 2z)<sup>2</sup> = 1/9, so z/(0.50 - 2z) = 1/3 and 3z = 0.50 - 2z, z = 0.10.</p><p>p(HI) = 0.50 - 0.20 = <b>0.30 atm</b>.</p>'),
    nat('ce-085', 5, 'mixed: chemical kinetics', 'For a reversible reaction the activation energy of the forward reaction is 100 kJ mol<sup>-1</sup> and that of the reverse reaction is 120 kJ mol<sup>-1</sup>. Find &Delta;H in kJ mol<sup>-1</sup> for the forward reaction.', -20, 0.5, 'kJ mol<sup>-1</sup>', '<p>&Delta;H = E<sub>a</sub>(forward) - E<sub>a</sub>(reverse) = 100 - 120 = <b>-20 kJ mol<sup>-1</sup></b>. The reaction is exothermic, so K falls with a rise in temperature (k<sub>b</sub> grows faster than k<sub>f</sub> because E<sub>a</sub>(reverse) is higher).</p>', 'Mixed with chemical kinetics.'),
    mk('ce-086', 5, 'degree of dissociation', 'For A(g) &#8652; 2B(g) with small degree of dissociation &alpha; (so 1 - &alpha;<sup>2</sup> &asymp; 1), if the total pressure is made four times larger at constant T, the new &alpha; is about', 'half of the old &alpha;', ['one quarter of the old &alpha;', 'twice the old &alpha;', 'unchanged'], '<p>K<sub>p</sub> = 4&alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>) &asymp; 4&alpha;<sup>2</sup>P. With K<sub>p</sub> fixed, &alpha; &prop; P<sup>-1/2</sup>. P &times; 4 gives &alpha; &times; 1/2.</p>', 'Square root, not direct proportion.'),
    mk('ce-087', 5, 'van&rsquo;t Hoff graph', 'The graph of ln K (y-axis) against 1/T (x-axis) is a straight line with a <b>positive</b> slope. The reaction is', 'exothermic, and K decreases as T increases', ['endothermic, and K increases as T increases', 'exothermic, and K increases as T increases', 'endothermic, and K decreases as T increases'], '<p>ln K = -&Delta;H/(RT) + constant, so slope = -&Delta;H/R. A positive slope means &Delta;H &lt; 0 (exothermic). Rising T lowers 1/T, so ln K decreases along the positive slope.</p>', 'Reading the axis as T instead of 1/T reverses the trend.'),
    msq('ce-088', 5, 'temperature effect', 'The temperature of a mixture at equilibrium for an exothermic reaction is raised. Which are correct?', ['The rate constants of both the forward and the reverse reactions increase', 'K decreases', 'The rate of the forward reaction decreases', 'E<sub>a</sub> of the reverse reaction is greater than E<sub>a</sub> of the forward reaction'], [0, 1, 3], '<p>Both rate constants increase with T (Arrhenius), but the reverse increases by more (higher E<sub>a</sub>), so K = k<sub>f</sub>/k<sub>b</sub> decreases. The forward rate does not decrease; it increases.</p>'),
    msq('ce-089', 5, 'simultaneous equilibria', 'In a vessel, A(g) &#8652; B(g) (K<sub>1</sub>) and A(g) &#8652; C(g) (K<sub>2</sub>) both reach equilibrium. Which are correct?', ['[B]/[C] = K<sub>1</sub>/K<sub>2</sub>', '[B] + [C] + [A] is constant if A was the only starting species', 'K for B &#8652; C is K<sub>2</sub>/K<sub>1</sub>', 'The ratio [B]/[C] depends on the initial amount of A'], [0, 1, 2], '<p>[B] = K<sub>1</sub>[A] and [C] = K<sub>2</sub>[A]. So [B]/[C] = K<sub>1</sub>/K<sub>2</sub>, independent of how much A was added. For B &#8652; C, K = [C]/[B] = K<sub>2</sub>/K<sub>1</sub>. Mass (moles) conservation holds (equal moles, constant volume).</p>'),
    stm('ce-090', 5, 'inert gas', 'For PCl<sub>5</sub> &#8652; PCl<sub>3</sub> + Cl<sub>2</sub>, adding an inert gas at constant total pressure increases the degree of dissociation.', 'At constant total pressure, adding an inert gas increases the volume, which lowers the partial pressure of each reacting gas.', 0, '<p>Both are correct. Larger volume lowers partial pressures, which favours the side with more moles (dissociation), so &alpha; rises. II is the explanation.</p>'),
  ],
  gens: [
    { id: 'ce-g01', type: 'nat', level: 2, exams: EX[2], sub: 'calculating K<sub>c</sub>',
      make(rng) {
        const a = pick(rng, 0.2, 1.0, 0.1); const b = pick(rng, 0.5, 2.0, 0.5); const c = pick(rng, 0.2, 1.0, 0.1);
        const K = c * c / (a * b ** 3);
        return { q: `At equilibrium, N<sub>2</sub>(g) + 3H<sub>2</sub>(g) &#8652; 2NH<sub>3</sub>(g) has [N<sub>2</sub>] = ${a}, [H<sub>2</sub>] = ${b} and [NH<sub>3</sub>] = ${c} mol L<sup>-1</sup>. Find K<sub>c</sub> (in L<sup>2</sup> mol<sup>-2</sup>).`, answer: +K.toPrecision(4), tol: Math.abs(K) * 0.01, unit: 'L<sup>2</sup> mol<sup>-2</sup>', a, b, c,
          sol: `<p>K<sub>c</sub> = [NH<sub>3</sub>]<sup>2</sup>/([N<sub>2</sub>][H<sub>2</sub>]<sup>3</sup>) = (${c})<sup>2</sup>/(${a} &times; ${b}<sup>3</sup>) = ${(c * c).toFixed(3)}/${(a * b ** 3).toFixed(3)} = <b>${fmt(K, 3)}</b>.</p>` };
      }, verify: (p) => (p.c ** 2) / (p.a * p.b * p.b * p.b) },
    { id: 'ce-g02', type: 'nat', level: 2, exams: EX[2], sub: 'K<sub>p</sub> and K<sub>c</sub>',
      make(rng) {
        const r = choose(rng, RX.filter((x) => x[1] !== 0)); const T = pick(rng, 300, 800, 100); const Kc = pick(rng, 0.5, 8, 0.5);
        const Kp = Kc * Math.pow(RT(T), r[1]);
        return { q: `For ${r[0]}, K<sub>c</sub> = ${Kc} (units of mol and L) at ${T} K. Find K<sub>p</sub> (pressures in atm). (R = 0.0821 L atm K<sup>-1</sup> mol<sup>-1</sup>)`, answer: +Kp.toPrecision(4), tol: Kp * 0.01, Kc, T, dn: r[1],
          sol: `<p>K<sub>p</sub> = K<sub>c</sub>(RT)<sup>&Delta;n<sub>g</sub></sup>, with &Delta;n<sub>g</sub> = ${r[1]} and RT = 0.0821 &times; ${T} = ${RT(T).toFixed(2)}.</p><p>K<sub>p</sub> = ${Kc} &times; (${RT(T).toFixed(2)})<sup>${r[1]}</sup> = <b>${fmt(Kp, 3)}</b> (unit ${UNITP[r[1]]}).</p>` };
      }, verify: (p) => p.Kc * Math.pow(0.0821 * p.T, p.dn) },
    { id: 'ce-g03', type: 'nat', level: 3, exams: EX[3], sub: 'K<sub>p</sub> and K<sub>c</sub>',
      make(rng) {
        const r = choose(rng, RX.filter((x) => x[1] !== 0)); const T = pick(rng, 300, 800, 100); const Kp = pick(rng, 1, 10, 1) * Math.pow(10, int(rng, -2, 1));
        const Kc = Kp / Math.pow(RT(T), r[1]);
        return { q: `For ${r[0]}, K<sub>p</sub> = ${fmt(Kp, 3)} (atm units) at ${T} K. Find K<sub>c</sub> (mol and L units). (R = 0.0821 L atm K<sup>-1</sup> mol<sup>-1</sup>)`, answer: +Kc.toPrecision(4), tol: Kc * 0.01, Kp, T, dn: r[1],
          sol: `<p>K<sub>c</sub> = K<sub>p</sub>(RT)<sup>-&Delta;n<sub>g</sub></sup>, &Delta;n<sub>g</sub> = ${r[1]}, RT = ${RT(T).toFixed(2)}.</p><p>K<sub>c</sub> = ${fmt(Kp, 3)} &times; (${RT(T).toFixed(2)})<sup>${-r[1]}</sup> = <b>${fmt(Kc, 3)}</b>.</p>` };
      }, verify: (p) => p.Kp / Math.pow(0.0821 * p.T, p.dn) },
    { id: 'ce-g04', type: 'nat', level: 2, exams: EX[2], sub: 'changing the equation',
      make(rng) {
        const mode = int(rng, 0, 3); const K = mode === 0 || mode === 3 ? choose(rng, [4, 9, 16, 25, 36, 64]) : choose(rng, [2, 3, 4, 5, 10]);
        const txt = ['the equation is halved (all coefficients &times; &frac12;)', 'the equation is doubled', 'the equation is reversed', 'the equation is reversed and then halved'][mode];
        const ans = [Math.sqrt(K), K * K, 1 / K, 1 / Math.sqrt(K)][mode];
        const tx = ['K<sup>1/2</sup>', 'K<sup>2</sup>', '1/K', 'K<sup>-1/2</sup>'][mode];
        return { q: `A reaction has K = ${K} at a given temperature. Find the equilibrium constant at the same temperature when ${txt}.`, answer: +ans.toPrecision(4), tol: ans * 0.005, K, mode,
          sol: `<p>The new constant is ${tx}.</p><p>= <b>${fmt(ans, 4)}</b>.</p>` };
      }, verify: (p) => [Math.sqrt(p.K), p.K ** 2, 1 / p.K, p.K ** -0.5][p.mode] },
    { id: 'ce-g05', type: 'nat', level: 3, exams: EX[3], sub: 'vapour density',
      make(rng) {
        const al = pick(rng, 0.1, 0.6, 0.05); const d = +(104.25 / (1 + al)).toFixed(2); const ans = +((104.25 - d) / d).toFixed(3);
        return { q: `The theoretical vapour density of PCl<sub>5</sub> is 104.25. At a certain temperature the equilibrium mixture of PCl<sub>5</sub> &#8652; PCl<sub>3</sub> + Cl<sub>2</sub> has a vapour density of ${d}. Find the degree of dissociation.`, answer: ans, tol: 0.006, D: 104.25, d,
          sol: `<p>Moles increase from 1 to 1 + &alpha;, so D/d = 1 + &alpha;.</p><p>&alpha; = (104.25 - ${d})/${d} = <b>${ans}</b>.</p>` };
      }, verify: (p) => p.D / p.d - 1 },
    { id: 'ce-g06', type: 'nat', level: 3, exams: EX[3], sub: 'degree of dissociation',
      make(rng) {
        const al = pick(rng, 0.1, 0.6, 0.05); const P = choose(rng, [0.5, 1, 2, 4]); const Kp = 4 * al * al * P / (1 - al * al);
        return { q: `N<sub>2</sub>O<sub>4</sub>(g) &#8652; 2NO<sub>2</sub>(g) is ${(al * 100).toFixed(0)}% dissociated at a total pressure of ${P} atm. Find K<sub>p</sub> in atm.`, answer: +Kp.toPrecision(4), tol: Kp * 0.01, al, P,
          sol: `<p>For 1 mol: N<sub>2</sub>O<sub>4</sub> = ${(1 - al).toFixed(2)}, NO<sub>2</sub> = ${(2 * al).toFixed(2)}, total = ${(1 + al).toFixed(2)}.</p><p>K<sub>p</sub> = 4&alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>) = 4(${al})<sup>2</sup>(${P})/(1 - ${(al * al).toFixed(4)}) = <b>${fmt(Kp, 3)} atm</b>.</p>` };
      }, verify: (p) => { const t = 1 + p.al; return ((2 * p.al * p.P / t) ** 2) / ((1 - p.al) * p.P / t); } },
    { id: 'ce-g07', type: 'nat', level: 3, exams: EX[3], sub: 'degree of dissociation',
      make(rng) {
        const al = pick(rng, 0.1, 0.8, 0.05); const P = choose(rng, [0.5, 1, 2, 5]); const Kp = al * al * P / (1 - al * al);
        return { q: `PCl<sub>5</sub>(g) &#8652; PCl<sub>3</sub>(g) + Cl<sub>2</sub>(g) is ${(al * 100).toFixed(0)}% dissociated at a total pressure of ${P} atm. Find K<sub>p</sub> in atm.`, answer: +Kp.toPrecision(4), tol: Kp * 0.01, al, P,
          sol: `<p>For 1 mol: PCl<sub>5</sub> = ${(1 - al).toFixed(2)}; PCl<sub>3</sub> = Cl<sub>2</sub> = ${al}; total = ${(1 + al).toFixed(2)}.</p><p>K<sub>p</sub> = &alpha;<sup>2</sup>P/(1 - &alpha;<sup>2</sup>) = (${al})<sup>2</sup>(${P})/(1 - ${(al * al).toFixed(4)}) = <b>${fmt(Kp, 3)} atm</b>.</p>` };
      }, verify: (p) => { const t = 1 + p.al; return ((p.al * p.P / t) ** 2) / ((1 - p.al) * p.P / t); } },
    { id: 'ce-g08', type: 'nat', level: 3, exams: EX[3], sub: 'ICE table',
      make(rng) {
        const k = choose(rng, [2, 3, 4, 6, 8]); const Kc = k * k; const hi = 2 * k / (2 + k);
        return { q: `One mole each of H<sub>2</sub> and I<sub>2</sub> are placed in a 1 L vessel. K<sub>c</sub> for H<sub>2</sub> + I<sub>2</sub> &#8652; 2HI is ${Kc} at that temperature. Find the moles of HI at equilibrium.`, answer: +hi.toFixed(3), tol: 0.01, unit: 'mol', k, Kc,
          sol: `<p>Let x mol of each react: [HI] = 2x, [H<sub>2</sub>] = [I<sub>2</sub>] = 1 - x. K<sub>c</sub> = (2x)<sup>2</sup>/(1 - x)<sup>2</sup> = ${Kc}.</p><p>Taking square roots: 2x/(1 - x) = ${k}, so x = ${k}/${2 + k} and HI = 2x = <b>${hi.toFixed(3)} mol</b>.</p>` };
      }, verify: (p) => { const x = (p.k) / (2 + p.k); return 2 * x; } },
    { id: 'ce-g09', type: 'nat', level: 3, exams: EX[3], sub: 'van&rsquo;t Hoff equation',
      make(rng) {
        const dH = pick(rng, 20, 100, 10); const T1 = choose(rng, [300, 350, 400]); const T2 = T1 + choose(rng, [10, 20, 25, 50]);
        const ans = Math.exp((dH * 1000 / 8.314) * (1 / T1 - 1 / T2));
        return { q: `A reaction has &Delta;H = +${dH} kJ mol<sup>-1</sup>. By what factor (K<sub>2</sub>/K<sub>1</sub>) does K change when the temperature goes from ${T1} K to ${T2} K? (R = 8.314; &Delta;H constant)`, answer: +ans.toPrecision(4), tol: ans * 0.01, dH, T1, T2,
          sol: `<p>ln(K<sub>2</sub>/K<sub>1</sub>) = (&Delta;H/R)(1/T<sub>1</sub> - 1/T<sub>2</sub>) = (${dH * 1000}/8.314)(1/${T1} - 1/${T2}) = ${Math.log(ans).toFixed(3)}.</p><p>K<sub>2</sub>/K<sub>1</sub> = <b>${fmt(ans, 3)}</b>.</p>` };
      }, verify: (p) => Math.pow(10, (p.dH * 1000 / (2.303 * 8.314)) * (1 / p.T1 - 1 / p.T2)) },
    { id: 'ce-g10', type: 'nat', level: 4, exams: EX[4], sub: 'van&rsquo;t Hoff equation',
      make(rng) {
        const dH = pick(rng, 30, 90, 10) * (rng() < 0.5 ? -1 : 1); const T1 = 300; const T2 = choose(rng, [350, 400, 500]); const K1 = choose(rng, [1, 10, 100]);
        const K2 = +(K1 * Math.exp((dH * 1000 / 8.314) * (1 / T1 - 1 / T2))).toPrecision(4);
        const ans = 8.314 * Math.log(K2 / K1) / (1 / T1 - 1 / T2) / 1000;
        return { q: `For a reaction, K = ${K1} at ${T1} K and K = ${K2} at ${T2} K. Find &Delta;H in kJ mol<sup>-1</sup>, assuming it is constant. (R = 8.314)`, answer: +ans.toFixed(2), tol: 0.5, K1, K2, T1, T2,
          sol: `<p>&Delta;H = R ln(K<sub>2</sub>/K<sub>1</sub>)/(1/T<sub>1</sub> - 1/T<sub>2</sub>) = 8.314 &times; ln(${K2}/${K1}) / (1/${T1} - 1/${T2}).</p><p>= 8.314 &times; ${Math.log(K2 / K1).toFixed(3)} / ${(1 / T1 - 1 / T2).toExponential(3)} = <b>${ans.toFixed(1)} kJ mol<sup>-1</sup></b>${ans > 0 ? ' (K rises with T: endothermic)' : ' (K falls with T: exothermic)'}.</p>` };
      }, verify: (p) => (Math.log(p.K2 / p.K1) * 8.314 * p.T1 * p.T2) / (p.T2 - p.T1) / 1000 },
    { id: 'ce-g11', type: 'mcq', level: 2, exams: EX[2], sub: 'reaction quotient',
      make(rng) {
        const r = choose(rng, [2, 3, 4]); const a = choose(rng, [0.1, 0.2, 0.5]); const mode = int(rng, 0, 2);
        const c = [(r - 1) * a, r * a, (r + 1) * a][mode]; const K = r * r; const Q = (c * c) / (a * a);
        const right = ['The reaction goes forward', 'The reaction is at equilibrium', 'The reaction goes backward'][mode];
        const { options, answer } = shuffleOpts(rng, right, ['The reaction goes forward', 'The reaction is at equilibrium', 'The reaction goes backward', 'Cannot be decided without a catalyst'].filter((x) => x !== right));
        return { q: `For A(g) + B(g) &#8652; C(g) + D(g), K<sub>c</sub> = ${K}. A mixture has [A] = [B] = ${a} and [C] = [D] = ${+c.toFixed(3)} mol L<sup>-1</sup>. Which statement is correct?`, options, answer, a, c, K, right,
          sol: `<p>Q<sub>c</sub> = [C][D]/([A][B]) = (${+c.toFixed(3)})<sup>2</sup>/(${a})<sup>2</sup> = ${+Q.toFixed(2)}.</p><p>Compare with K<sub>c</sub> = ${K}: ${Q < K - 1e-9 ? 'Q &lt; K, so products form (forward)' : Q > K + 1e-9 ? 'Q &gt; K, so products are used up (backward)' : 'Q = K, so equilibrium'}. <b>${right}</b>.</p>` };
      }, verify: (p) => p.options.indexOf(p.right) },
    { id: 'ce-g12', type: 'nat', level: 3, exams: EX[3], sub: 'mixed: thermodynamics',
      make(rng) {
        const m = int(rng, -3, 6); const T = choose(rng, [298, 300, 310, 350]); const dG = -m * 2.303 * 8.314 * T / 1000;
        return { q: `At ${T} K the equilibrium constant of a reaction is 10<sup>${m}</sup>. Find &Delta;G&deg; in kJ mol<sup>-1</sup>. (R = 8.314)`, answer: +dG.toFixed(2), tol: 0.1, unit: 'kJ mol<sup>-1</sup>', m, T,
          sol: `<p>&Delta;G&deg; = -2.303RT log K = -2.303 &times; 8.314 &times; ${T} &times; (${m}) = <b>${dG.toFixed(2)} kJ mol<sup>-1</sup></b>.</p>${m < 0 ? '<p>K &lt; 1, so &Delta;G&deg; is positive.</p>' : ''}` };
      }, verify: (p) => (-p.m * Math.LN10 * 8.314 * p.T) / 1000 },
    { id: 'ce-g13', type: 'nat', level: 3, exams: EX[3], sub: 'degree of dissociation',
      make(rng) {
        const al = pick(rng, 0.1, 0.8, 0.1); const P0 = pick(rng, 0.5, 4, 0.5); const Pt = P0 * (1 + al);
        return { q: `Pure A(g) at ${P0} atm is placed in a rigid vessel and dissociates as A(g) &#8652; B(g) + C(g). At equilibrium the total pressure is ${+Pt.toFixed(3)} atm at the same temperature. Find the degree of dissociation.`, answer: al, tol: 0.01, P0, Pt: +Pt.toFixed(3),
          sol: `<p>For A &#8652; B + C at constant volume, pressure is proportional to moles. Moles go from 1 to 1 + &alpha;.</p><p>P<sub>total</sub> = P<sub>0</sub>(1 + &alpha;), so &alpha; = ${+Pt.toFixed(3)}/${P0} - 1 = <b>${al}</b>.</p>` };
      }, verify: (p) => p.Pt / p.P0 - 1 },
    { id: 'ce-g14', type: 'nat', level: 2, exams: EX[2], sub: 'heterogeneous equilibrium',
      make(rng) {
        const kind = int(rng, 0, 1); const P = pick(rng, 0.2, 2, 0.1);
        const Kp = kind === 0 ? (P / 2) ** 2 : 4 * P ** 3 / 27;
        return { q: kind === 0 ? `NH<sub>4</sub>HS(s) &#8652; NH<sub>3</sub>(g) + H<sub>2</sub>S(g). At equilibrium the total pressure in the vessel is ${P} atm. Find K<sub>p</sub> in atm<sup>2</sup>.` : `NH<sub>2</sub>COONH<sub>4</sub>(s) &#8652; 2NH<sub>3</sub>(g) + CO<sub>2</sub>(g). At equilibrium the total pressure is ${P} atm. Find K<sub>p</sub> in atm<sup>3</sup>.`, answer: +Kp.toPrecision(4), tol: Kp * 0.01, kind, P,
          sol: kind === 0 ? `<p>The two gases are in equal amounts, so each has p = ${P}/2 = ${P / 2} atm. K<sub>p</sub> = (${P / 2})<sup>2</sup> = <b>${fmt(Kp, 3)} atm<sup>2</sup></b>.</p>` : `<p>The gases are in the ratio 2 : 1, so p(NH<sub>3</sub>) = 2P/3 = ${fmt(2 * P / 3, 3)} and p(CO<sub>2</sub>) = P/3 = ${fmt(P / 3, 3)} atm.</p><p>K<sub>p</sub> = (2P/3)<sup>2</sup>(P/3) = 4P<sup>3</sup>/27 = <b>${fmt(Kp, 3)} atm<sup>3</sup></b>.</p>` };
      }, verify: (p) => (p.kind === 0 ? (p.P / 2) ** 2 : ((2 * p.P) / 3) ** 2 * (p.P / 3)) },
    { id: 'ce-g15', type: 'mcq', level: 1, exams: EX[1], sub: 'units of K',
      make(rng) {
        const r = choose(rng, RX); const dn = r[1]; const right = UNIT[dn];
        const all = Object.values(UNIT);
        const { options, answer } = shuffleOpts(rng, right, all.filter((x) => x !== right).slice(0, 3));
        return { q: `The unit of K<sub>c</sub> (concentrations in mol L<sup>-1</sup>) for ${r[0]} is`, options, answer, dn, right,
          sol: `<p>&Delta;n = (moles of gaseous products) - (moles of gaseous reactants) = ${dn}. The unit is (mol L<sup>-1</sup>)<sup>${dn}</sup> = <b>${right}</b>.</p>` };
      }, verify: (p) => p.options.indexOf(UNIT[p.dn]) },
    { id: 'ce-g16', type: 'nat', level: 4, exams: EX[4], sub: 'ICE table',
      make(rng) {
        const c0 = choose(rng, [1, 2]); const x2 = +(pick(rng, 0.2, 0.8, 0.1) * c0).toFixed(2);
        const Kc = +(x2 * x2 / (c0 - x2)).toFixed(4);
        return { q: `A(g) &#8652; B(g) + C(g) has K<sub>c</sub> = ${Kc} mol L<sup>-1</sup>. The vessel starts with ${c0} mol L<sup>-1</sup> of A only. Find [B] at equilibrium in mol L<sup>-1</sup>.`, answer: x2, tol: 0.01, unit: 'mol L<sup>-1</sup>', c0, Kc, x2,
          sol: `<p>Let [B] = [C] = x and [A] = ${c0} - x. Then x<sup>2</sup>/(${c0} - x) = ${Kc}, i.e. x<sup>2</sup> + ${Kc}x - ${+(Kc * c0).toFixed(4)} = 0.</p><p>x = [-${Kc} + &radic;(${Kc}<sup>2</sup> + 4 &times; ${+(Kc * c0).toFixed(4)})]/2 = <b>${x2}</b>.</p>` };
      }, verify: (p) => { const b = p.Kc, c = -p.Kc * p.c0; return (-b + Math.sqrt(b * b - 4 * c)) / 2; } },
  ],
};
